import {filterObservations} from './archive.mjs';
import {workbenchMessage} from '../environment/workbench-messages.mjs';
import {environmentMessage} from '../environment/messages.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>workbenchMessage(k,I18n.language),number=v=>Number.isFinite(v)?new Intl.NumberFormat(I18n.locale,{maximumFractionDigits:3}).format(v):t('notProvided');
export class ObservationController{
  constructor(container,repository,service,{openPanel=()=>{},onChange=()=>{}}={}){this.container=container;this.repository=repository;this.service=service;this.openPanel=openPanel;this.onChange=onChange;this.data=null;this.map=null;this.group=null;this.uncertaintyCircle=null;this.worker=null;this.generation=0;this.status='';this.busy=false;this.selected=null;this.context=null;this.page=0;this.filters={year:'2025',month:'all',maxUncertainty:1000,show:true,followMap:true};this.period=null;container.dataset.userContent='';
    container.addEventListener('click',e=>{const action=e.target.closest('[data-observation-action]')?.dataset.observationAction;if(action==='import')container.querySelector('input[type=file]').click();if(action==='fit')this.fit();if(action==='remove')this.remove();if(action==='context')this.queryContext();if(action==='more'){this.page++;this.render();}if(action==='previous'&&this.page>0){this.page--;this.render();}const pick=e.target.closest('[data-observation-index]');if(pick)this.select(this.filtered[Number(pick.dataset.observationIndex)]);});
    container.addEventListener('change',e=>{if(e.target.type==='file'){const f=e.target.files[0];if(f)this.importFile(f);return;}const key=e.target.dataset.observationFilter;if(!key)return;this.filters[key]=e.target.type==='checkbox'?e.target.checked:key==='maxUncertainty'?Number(e.target.value):e.target.value;if(key==='year'||key==='month')this.filters.followMap=false;if(key==='followMap'&&this.filters.followMap&&this.period)this.syncPeriod(this.period);this.selected=null;this.context=null;this.page=0;++this.generation;this.render();});this.render();
  }
  async restore(){this.data=await this.repository.load();if(this.data){this.render();this.onChange();}}
  attachMap(map){if(this.map===map)return;this.map=map;map.createPane('observationsPane').style.zIndex=460;this.renderer=window.L.canvas({pane:'observationsPane',padding:.1});map.on('moveend zoomend',()=>{if(!this.queued){this.queued=true;requestAnimationFrame(()=>{this.queued=false;this.draw();});}});this.draw();}
  syncPeriod(period){const changed=this.period!==period;this.period=period;if(this.filters.followMap){this.filters.year=period.slice(0,4);this.filters.month=String(Number(period.slice(5,7)));if(changed){this.selected=null;this.context=null;this.page=0;++this.generation;}}this.render();}
  async importFile(file){const generation=this.importGeneration=(this.importGeneration||0)+1;++this.generation;this.worker?.terminate();this.busy=true;this.status='';this.render();try{if(!file.size||file.size>25*1024*1024||!file.name.toLowerCase().endsWith('.zip'))throw Error('invalid_archive_file');const bytes=await file.arrayBuffer();if(generation!==this.importGeneration)return;const worker=new Worker(new URL('./import-worker.mjs',import.meta.url),{type:'module'});this.worker=worker;const data=await new Promise((resolve,reject)=>{worker.onmessage=e=>e.data.ok?resolve(e.data.data):reject(Error(e.data.error));worker.onerror=()=>reject(Error('archive_worker_failed'));worker.postMessage({bytes,fileName:file.name},[bytes]);});worker.terminate();if(generation!==this.importGeneration)return;await this.repository.save(data);if(generation!==this.importGeneration)return;this.data=data;this.selected=null;this.context=null;this.page=0;this.status=this.repository.persistence==='memory'?'storageMemory':'';this.onChange();}catch(error){if(generation===this.importGeneration){this.status='archiveError';this.errorCode=error.message;}}finally{if(generation===this.importGeneration){this.busy=false;this.render();}}}
  async remove(){++this.generation;this.importGeneration=(this.importGeneration||0)+1;this.worker?.terminate();try{await this.repository.remove();this.data=null;this.selected=null;this.context=null;this.busy=false;this.status='';this.render();this.onChange();}catch{this.status='archiveError';this.render();}}
  render(){
    const data=this.data,f=this.filters;this.filtered=data?filterObservations(data,{year:f.year,month:f.month,maxUncertainty:f.maxUncertainty}):[];const count=this.filtered.length,years=data?Object.keys(data.metadata.years).sort().reverse():[],select=(key,options)=>`<select data-observation-filter="${key}">${options.map(([value,label])=>`<option value="${value}" ${String(f[key])===String(value)?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
    this.container.innerHTML=`<div class="observation-intro"><span class="workbench-tag">${esc(t('research'))}</span><h3>${esc(t('archiveTitle'))}</h3><p>${esc(t('localNote'))}</p></div><input type="file" accept=".zip" hidden><button class="btn primary full" data-observation-action="import" ${this.busy?'disabled':''}>${esc(t(this.busy?'importing':'importArchive'))}</button>${this.status?`<p class="environment-query-warning" role="status">${esc(t(this.status))}</p>`:''}${data?`<div class="observation-summary" role="status"><div><strong>${number(data.metadata.recordCount)}</strong><span>${esc(t('records'))}</span></div><div><strong>${number(count)}</strong><span>${esc(t('displayed'))}</span></div></div><label class="environment-checkbox"><input type="checkbox" data-observation-filter="show" ${f.show?'checked':''}><span>${esc(t('showObs'))}</span></label><label class="environment-checkbox"><input type="checkbox" data-observation-filter="followMap" ${f.followMap?'checked':''}><span>${esc(t('linkMonth'))}</span></label><div class="observation-filters"><label>${esc(t('year'))}${select('year',[['all',t('allYears')],...years.map(y=>[y,y])])}</label><label>${esc(t('month'))}${select('month',[['all',t('allMonths')],...Array.from({length:12},(_,i)=>[String(i+1),new Intl.DateTimeFormat(I18n.locale,{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2025,i,1)))])])}</label></div><label>${esc(t('maxUncertainty'))}${select('maxUncertainty',[[1000,t('within1km')],[12000,t('within12km')],[Infinity,t('allQuality')]])}</label><button class="btn secondary full" data-observation-action="fit" ${count?'':'disabled'}>${esc(t('fitObs'))}</button>${!count?`<p>${esc(t('noMatches'))}</p>`:''}<p class="small-note">${esc(t('presenceNote'))}</p><div class="observation-list">${this.filtered.slice(this.page*10,this.page*10+10).map((r,i)=>`<button data-observation-index="${this.page*10+i}" class="observation-row"><span>${esc(r.date.slice(0,10))}<small>${number(r.lat)} / ${number(r.lon)}</small></span><span>${r.uncertaintyMeters==null?'—':number(r.uncertaintyMeters)+' m'} ↗</span></button>`).join('')}</div>${count>10?`<div class="observation-pagination"><button class="text-link" data-observation-action="previous" aria-label="${esc(t('previousRecords'))}" ${this.page?'':'disabled'}>←</button><span>${this.page*10+1}–${Math.min(count,this.page*10+10)} / ${count}</span><button class="text-link" data-observation-action="more" aria-label="${esc(t('nextRecords'))}" ${count>(this.page+1)*10?'':'disabled'}>→</button></div>`:''}${this.selected?this.selectionHTML(this.selected):''}`:`<p>${esc(t('archiveEmpty'))}</p>`}<details class="environment-notes"><summary>${esc(t('details'))}</summary><p>${esc(t('archiveLicense'))}</p><p>${esc(t('dateCaution'))}</p>${data?`<p>${esc(t('metadataConflict'))}</p><dl class="environment-facts"><div><dt>SHA-256</dt><dd>${esc(data.metadata.archiveSha256)}</dd></div><div><dt>${esc(t('records'))}</dt><dd>${number(data.metadata.recordCount)}</dd></div><div><dt>${esc(t('excluded'))}</dt><dd>${number(Object.values(data.metadata.quarantine).reduce((a,b)=>a+b,0))}</dd></div></dl>`:''}<a href="https://seamap.env.duke.edu/dataset/1764/html" target="_blank" rel="noopener">Happywhale / OBIS-SEAMAP ↗</a></details>${data?`<button class="text-link observation-remove" data-observation-action="remove">${esc(t('removeObs'))}</button>`:''}`;
    this.draw();
  }
  selectionHTML(r){const rows=[[t('observedDate'),r.date],[t('maxUncertainty'),r.uncertaintyMeters==null?t('notProvided'):number(r.uncertaintyMeters)+' m'],[t('recordId'),r.id],[t('animalId'),r.animalId||'—'],[t('photoLicense'),r.pictureLicense]];return `<div class="observation-selection"><h3>${esc(t('selectedObservation'))}</h3><p><i>Megaptera novaeangliae</i></p><dl class="environment-facts">${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p>${esc(t('dateCaution'))}</p><button class="btn secondary full" data-observation-action="context">${esc(t('contextQuery'))}</button><p class="small-note">${esc(t('contextNote'))}</p>${this.contextHTML()}</div>`;}
  contextHTML(){if(!this.context)return '';if(this.context==='loading')return `<p role="status">${esc(environmentMessage('loading',I18n.language))}</p>`;return `<div class="observation-environment-context" role="status">${Object.entries(this.context).map(([key,r])=>`<div><strong>${esc(key==='sst'?environmentMessage('sst',I18n.language):t('currents'))}</strong><span>${r.status==='available'?number(typeof r.value==='object'?r.vector.speed:r.value)+' '+r.units:esc(workbenchMessage(r.status,I18n.language)===r.status?environmentMessage(r.reason||r.status,I18n.language):t(r.status))}</span><small>${esc(r.time||'—')}</small><details class="environment-result-source"><summary>${esc(t('details'))}</summary><dl class="environment-facts"><div><dt>${esc(environmentMessage('source',I18n.language))}</dt><dd>${esc(r.source?.originalFile||'—')}</dd></div><div><dt>${esc(environmentMessage('cell',I18n.language))}</dt><dd>${r.gridCell?number(r.gridCell.latitude)+' / '+number(r.gridCell.longitude):'—'}</dd></div><div><dt>${esc(t('uncertainty'))}</dt><dd>${r.uncertainty?.value==null?esc(t('notProvided')):number(r.uncertainty.value)+' '+esc(r.uncertainty.units)}</dd></div><div><dt>${esc(environmentMessage('bounds',I18n.language))}</dt><dd>${r.sourceInterval?.start?esc(r.sourceInterval.start+' → '+r.sourceInterval.end):esc(t('noBounds'))}</dd></div></dl></details></div>`).join('')}</div>`;}
  async queryContext(){const r=this.selected;if(!r||!r.month||r.date.length<10)return;const generation=++this.generation;this.context='loading';this.render();const [sst,current]=await Promise.all([this.service.getEnvironmentalValue('sst',r.lat,r.lon,r.date.slice(0,10),{temporalMode:'interval-mean'}),this.service.getEnvironmentalValue('current_vector',r.lat,r.lon,r.date.slice(0,10),{temporalMode:'calendar-month'})]);if(generation!==this.generation||this.selected!==r)return;this.context={sst,current};this.render();this.container.querySelector('.observation-environment-context')?.scrollIntoView({block:'nearest'});}
  select(record){if(!record)return;++this.generation;this.selected=record;this.context=null;this.openPanel('observations');this.render();this.container.querySelector('.observation-selection')?.scrollIntoView({block:'nearest',behavior:'instant'});}
  draw(){if(!this.map)return;const L=window.L;if(this.group)this.map.removeLayer(this.group);if(this.uncertaintyCircle)this.map.removeLayer(this.uncertaintyCircle);this.group=null;this.uncertaintyCircle=null;if(!this.data||!this.filters.show)return;this.group=L.layerGroup().addTo(this.map);const occupied=new Map(),bounds=this.map.getBounds().pad(.1);for(const r of this.filtered||[]){if(!bounds.contains([r.lat,r.lon]))continue;const p=this.map.latLngToContainerPoint([r.lat,r.lon]),key=Math.floor(p.x/27)+':'+Math.floor(p.y/27);if(!occupied.has(key))occupied.set(key,[]);occupied.get(key).push(r);}for(const records of occupied.values()){const r=records[0],marker=records.length===1?L.circleMarker([r.lat,r.lon],{radius:5,weight:1.5,color:'#fff',fillColor:r.uncertaintyMeters>1000?'#ac734a':'#173f50',fillOpacity:1,bubblingMouseEvents:false,renderer:this.renderer}):L.marker([r.lat,r.lon],{pane:'observationsPane',bubblingMouseEvents:false,icon:L.divIcon({className:'observation-cluster',html:String(records.length),iconSize:[29,29],iconAnchor:[14,14]})});marker.on('click',()=>{if(records.length>1&&this.map.getZoom()<10){this.map.setView([r.lat,r.lon],this.map.getZoom()+2);return;}this.select(r);});marker.addTo(this.group);}if(this.selected&&this.selected.uncertaintyMeters>0)this.uncertaintyCircle=L.circle([this.selected.lat,this.selected.lon],{radius:this.selected.uncertaintyMeters,color:'#347b87',weight:1.5,dashArray:'5 5',fillOpacity:.08,interactive:false}).addTo(this.map);}
  fit(){if(this.filtered?.length&&this.map){this.filters.show=true;this.map.fitBounds(window.L.latLngBounds(this.filtered.map(r=>[r.lat,r.lon])),{maxZoom:8,padding:[45,45]});this.render();}}
}
